            'study.defaultFocusMinutes':{label:'Tempo de foco padrão',category:'Estudo',type:'number',unit:'min',description:'Duração padrão configurada para uma sessão de foco',getValue:()=>Number(Store.state.settings?.pomodoroTime??25)},
            'questions.total':{label:'Questões respondidas',category:'Questões',type:'number',description:'Total no histórico',getValue:()=> (Store.state.quizHistory||[]).length},
            'questions.accuracy':{label:'Acertos em questões',category:'Questões',type:'percent',description:'Percentual de acertos',getValue:()=>{const q=Store.state.quizHistory||[];return q.length?Math.round(q.filter(x=>x.result==='hit').length/q.length*100):0}},
            'reviews.pending':{label:'Revisões pendentes',category:'Revisões',type:'number',description:'Flashcards e conteúdos pendentes',getValue:()=> (window.StudySystem?.dueCards?.().length||0)+(window.StudySystem?.dueTopics?.().length||0)+(window.StudySystem?.errors?.().length||0)},
            'content.weakest':{label:'Conteúdo mais fraco',category:'Conteúdos',type:'text',description:'Conteúdo com menor domínio',getValue:()=>{const x=window.StudySystem?.weakTopics?.()[0];return x?`${x.subject} — ${x.topic}`:'Sem dados'}},
