                    item = { id: `topic-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, key, subject, topic, mastery: null, questionsAnswered: 0, questionsCorrect: 0, questionsWrong: 0, recentAnswers: [], examResults: [], reviewCount: 0, flashcardReviews: 0, lastStudiedAt: null, nextReviewAt: null, lastWrongAt: null, examIds: [], flashcardDeckIds: [], mindmapIds: [], createdAt: Date.now() };
                    Store.state.studyTopics.push(item);
