                const options = Array.isArray(question.options) ? question.options : [];
                if (!item) { item = { id: `error-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, key, questionId, subject: meta.subject, topic: meta.topic, question: this.label(question.text || question.question, 'Questão'), userAnswer: '', correctAnswer: '', explanation: String(question.explanation || question.explicacao || ''), errorType: 'concept', attempts: 0, createdAt: new Date().toISOString(), lastReviewedAt: null, mastered: false, source: context.source || 'question', examId: context.examId || null }; Store.state.errorNotebook.push(item); }
