                const now = Date.now(), currentInterval = Math.max(0, Number(card.interval || 0)), multipliers = { miss: 1, hard: Math.max(3, Math.round(currentInterval * 1.2)), good: Math.max(7, Math.round(currentInterval * 1.8)), easy: Math.max(20, Math.round(currentInterval * 2.5)) }, days = multipliers[rating] ?? 7;
                card.difficulty = rating; card.lastReviewedAt = new Date(now).toISOString(); card.reviewCount = Number(card.reviewCount || 0) + 1; card.lapses = Number(card.lapses || 0) + (rating === 'miss' ? 1 : 0); card.interval = days; card.nextReviewAt = new Date(now + days * 86400000).toISOString();
                topic.flashcardReviews = Number(topic.flashcardReviews || 0) + 1; topic.reviewCount = Number(topic.reviewCount || 0) + 1; topic.lastStudiedAt = new Date(now).toISOString(); if (rating === 'miss') topic.lastWrongAt = new Date(now).toISOString();
