            examPreparation(exam) { const topics = this.examTopics(exam).filter(topic => Number.isFinite(topic.mastery)); return topics.length ? Math.round(topics.reduce((sum, topic) => sum + topic.mastery, 0) / topics.length) : null; },
            subjectSummary(subject) { const normalized=this.normalize(subject),topics=(Store.state.studyTopics||[]).filter(topic=>this.normalize(topic.subject)===normalized&&Number.isFinite(topic.mastery)).sort((a,b)=>a.mastery-b.mastery),answers=topics.flatMap(topic=>(topic.recentAnswers||[]).filter(row=>typeof row.correct==='boolean')),totalQuestions=answers.length,correct=answers.filter(row=>row.correct).length,overall=topics.length?Math.round(topics.reduce((sum,topic)=>sum+topic.mastery,0)/topics.length):null,exams=this.upcomingExams().filter(exam=>this.normalize((exam.subjects||[]).join(' ')).includes(normalized));return{subject,overall,topics,accuracy:totalQuestions?Math.round(correct/totalQuestions*100):null,lastStudiedAt:topics.map(t=>t.lastStudiedAt).filter(Boolean).sort().at(-1)||null,nextExam:exams[0]||null}; },
            upcomingExams() { const now = new Date(); now.setHours(0,0,0,0); return (Store.state.exams || []).filter(exam => exam.date && new Date(`${exam.date}T00:00:00`) >= now).sort((a,b) => String(a.date).localeCompare(String(b.date))); },
