                const exams = GradeMath.examNames(this.formExamCount()), config = this.readCalculationForm(), grades = Object.fromEntries(exams.map((exam, index) => [exam, [8, 6, 10, 7][index] ?? 7])), sample = GradeMath.calculateAverage(grades, [], {}, config, exams);
