                document.querySelectorAll('.grade-term-button').forEach((button, index) => { const active = index + 1 === term; button.classList.toggle('bg-brand-600', active); button.classList.toggle('text-white', active); button.classList.toggle('text-txt-muted', !active); });
                this.renderDashboard(subjects, term);
