                if (!filteredSubjects.length) { grid.innerHTML = '<div class="lg:col-span-2 rounded-3xl border border-dashed border-white/10 p-12 text-center text-sm text-txt-muted">Nenhuma matéria encontrada para essa busca.</div>'; return; }
