                    const exams = this.exams(subject, term), reportedOnly = GradeMath.isGrade(data.reportedAverage) && !exams.some(exam => GradeMath.isGrade(data.grades[exam]));
                    const gradeCells = exams.map(exam => `<div class="rounded-xl bg-bg-main px-3 py-2 text-center"><small class="block text-[9px] font-black text-txt-muted">${exam}</small><b class="text-sm text-txt-main">${this.format(data.grades[exam], 1)}</b></div>`).join('');
                    return `<article onclick="Grades.openDetails('${subject.id}')" class="cursor-pointer rounded-3xl bg-bg-surface border border-white/5 p-5 transition-all hover:border-brand-400/40 hover:-translate-y-0.5 shadow-sm"><div class="flex items-start justify-between gap-4"><div class="min-w-0"><small class="text-[9px] font-black uppercase tracking-widest text-brand-500">${term}º trimestre · ${exams.length} prova(s)${reportedOnly ? ' · média do boletim' : ''}</small><h3 class="text-xl font-black text-txt-main truncate">${escapeHtml(subject.name)}</h3></div><div class="text-right shrink-0"><small class="block text-[9px] font-black uppercase text-txt-muted">Média</small><strong class="text-2xl text-txt-main">${this.format(average)}</strong></div></div><div class="grid grid-cols-2 sm:grid-cols-4 gap-2 mt-4">${gradeCells}</div><div class="mt-4 flex items-center justify-between gap-3"><span class="px-3 py-1.5 rounded-full text-[10px] font-black ${status[1]} ${status[2]}">${status[0]}</span>${neededText ? `<span class="text-right text-[10px] font-black ${needed.status === 'impossible' ? 'text-red-500' : 'text-brand-600'}">${escapeHtml(neededText)}</span>` : ''}</div></article>`;
